qrList.message:
/input default=1d20 Enter a dice formula (e.g. 1d20+3, 2d6, 4d6): |
/setvar key=_formula {{pipe}} |
/echo severity=info {{getvar::_formula}}  →  {{roll::{{getvar::_formula}}}}

/input default=1d8 Damage taken (number like 7, or formula like 2d6+1): |
/setvar key=_dmgf {{pipe}} |
/if left={{getvar::_dmgf}} right=d rule=in
  else={: /setvar key=_dmg {{getvar::_dmgf}} :}
  {: /setvar key=_dmg {{roll::{{getvar::_dmgf}}}} :} |
/sub {{getvar::hp}} {{getvar::_dmg}} |
/setvar key=hp {{pipe}} |
/if left={{getvar::hp}} right=0 rule=lte
  else={: /echo severity=warning Took {{getvar::_dmg}} damage. HP {{getvar::hp}}/{{getvar::maxhp}}. :}
  {: /setvar key=hp 0 | /setvar key=conditions unconscious | /echo severity=error Took {{getvar::_dmg}} damage — HP 0, you are DOWN! :}
